11	/**
12	 * Migration to convert jest.config.ts files from ESM to CJS syntax for projects
13	 * using CommonJS resolution. This is needed because Node.js type-stripping
14	 * in newer versions (22+, 24+) can cause issues with ESM syntax in .ts files
15	 * when the project is configured for CommonJS.
16	 *
17	 * Conversions:
18	 * - `export default { ... }` -> `module.exports = { ... }`
19	 * - `import { x } from 'y'` -> `const { x } = require('y')`
20	 * - `import x from 'y'` -> `const x = require('y').default ?? require('y')`
21	 *
22	 * ESM-only features that cannot be converted (will warn user):
23	 * - `import.meta`
24	 * - top-level `await`
25	 *
26	 * Projects with `type: module` in package.json are skipped and warned about,
27	 * as they use ESM semantics and don't need the CJS conversion.
28	 */
29	export default async function convertJestConfigToCjs(tree: Tree) {
30	  const { ast: parseAst, query } = require('@phenomnomnominal/tsquery');
31	
32	  const jestConfigPaths = await globAsync(tree, ['**/jest.config.ts']);
33	  const projectsWithEsmOnlyFeatures: string[] = [];
34	  const projectsWithTypeModule: string[] = [];
35	  const modifiedFiles: string[] = [];
36	
37	  for (const configPath of jestConfigPaths) {
38	    const projectRoot = dirname(configPath);
39	    const packageJsonPath = joinPathFragments(projectRoot, 'package.json');
40	    const rootPackageJsonPath = 'package.json';
41	
42	    // Check project-level package.json first, then root
43	    let projectPackageJson: { type?: string } | null = null;
44	    let rootPackageJson: { type?: string } | null = null;
45	
46	    if (tree.exists(packageJsonPath)) {
47	      projectPackageJson = readJson(tree, packageJsonPath);
48	    }
49	
50	    if (tree.exists(rootPackageJsonPath)) {
51	      rootPackageJson = readJson(tree, rootPackageJsonPath);
52	    }
53	
54	    const effectiveType =
55	      projectPackageJson?.type ?? rootPackageJson?.type ?? 'commonjs'; // CJS is default if missing
56	
57	    // If type is "module", skip conversion: the file already runs under ESM
58	    // semantics and does not need the CJS rewrite.
59	    if (effectiveType === 'module') {
60	      projectsWithTypeModule.push(configPath);
61	      continue;
62	    }
63	
64	    let content = tree.read(configPath, 'utf-8');
65	
66	    // Check for ESM-only features that can't be converted
67	    const hasImportMeta =
68	      query(content, 'MetaProperty').length > 0 ||
