114	function checkForTopLevelAwait(
115	  content: string,
116	  parseAst: any,
117	  query: any
118	): boolean {
119	  const ts = require('typescript');
120	  // Check for await expressions that are not inside a function
121	  const sourceFile = parseAst(content);
122	  const awaitExpressions = query(sourceFile, 'AwaitExpression');
123	
124	  for (const awaitExpr of awaitExpressions) {
125	    let parent = awaitExpr.parent;
126	    let isInsideFunction = false;
127	
128	    while (parent) {
129	      if (ts.isFunctionLike(parent)) {
130	        isInsideFunction = true;
131	        break;
132	      }
133	      parent = parent.parent;
134	    }
135	
136	    if (!isInsideFunction) {
137	      return true;
138	    }
139	  }
140	
141	  return false;
142	}
